const static uint32_t MAX_LEN = 55;

// XXX : The number of UTF-16 2byte code units are half the number of
// bytes in legacy encodings for CJK strings and non-Latin1 in UTF-8.
// The ratio can be 1/3 for CJK strings in UTF-8. However, we can
// get away with using the same MAX_LEN for nsCString and nsString
// because MAX_LEN is defined rather conservatively in the first place.
nsString NS_MsgHashIfNecessary(const nsACString& unsafeName) {
  return NS_MsgHashIfNecessary(NS_ConvertUTF8toUTF16(unsafeName));

char hashedname[9];
int32_t keptLength = -1;
if (illegalCharacterIndex != -1) {
  // The name is truncated at the illegal character, but never beyond the
  // length limit: the hashed name must fit within MAX_LEN like any other.
  keptLength = std::min(illegalCharacterIndex, (int32_t)MAX_LEN - 8);
} else if (name.Length() > MAX_LEN) {
  keptLength = MAX_LEN - 8;
}
if (keptLength == (int32_t)MAX_LEN - 8) {
  // To avoid keeping only the high surrogate of a surrogate pair
  if (mozilla::IsHighSurrogate(name.CharAt(keptLength - 1))) --keptLength;
}

if (keptLength >= 0) {
  PR_snprintf(hashedname, 9, "%08lx", (unsigned long)StringHash(name));
  name.SetLength(keptLength);
  name.Append(NS_ConvertASCIItoUTF16(hashedname));
}

// The name must not exceed 55 characters. It is truncated and a hash placed
// at the end.
input = u"test TEST test TEST test TEST test TEST test TEST test TEST"_ns;
ASSERT_TRUE(NS_MsgHashIfNecessary(input).Equals(
    u"test TEST test TEST test TEST test TEST test TEa2bbf4d7"_ns));

// The 55-character limit also applies when the name contains an illegal
// character further in: the name is truncated to 47 characters (not at the
// illegal character) before the hash is appended.
input = u"1234567890 1234567890 1234567890 1234567890 1234567890: tail"_ns;
ASSERT_TRUE(NS_MsgHashIfNecessary(input).Equals(
    u"1234567890 1234567890 1234567890 1234567890 123870c44d6"_ns));
